# Google Calendar API - Node.js Skill

## Overview
Access Google Calendar events using the Google Calendar API v3 with OAuth2 authentication.

## Setup
```bash
npm install googleapis
```

## Authentication
Use OAuth2 credentials (client_id, client_secret, refresh_token, access_token) from credentials.json and tokens.json files.

```javascript
const { google } = require('googleapis');

// Load credentials
const credentials = require('./auth/calendar/credentials.json');
const tokens = require('./auth/calendar/tokens.json');

const { client_id, client_secret } = credentials.installed;
const account = tokens.accounts[tokens.defaultAccount];

const oauth2Client = new google.auth.OAuth2(client_id, client_secret);
oauth2Client.setCredentials({
  access_token: account.access_token,
  refresh_token: account.refresh_token,
});

const calendar = google.calendar({ version: 'v3', auth: oauth2Client });
```

## List Events (Check Busy Times)
```javascript
// List events for a specific date range
const res = await calendar.events.list({
  calendarId: 'primary',
  timeMin: '2026-01-06T00:00:00-08:00',  // ISO 8601 format with timezone
  timeMax: '2026-01-09T23:59:59-08:00',
  singleEvents: true,
  orderBy: 'startTime',
});

const events = res.data.items || [];
events.forEach(event => {
  console.log(`${event.summary}: ${event.start.dateTime} - ${event.end.dateTime}`);
});
```

## FreeBusy Query (Check Availability)
```javascript
const res = await calendar.freebusy.query({
  requestBody: {
    timeMin: '2026-01-06T00:00:00-08:00',
    timeMax: '2026-01-09T23:59:59-08:00',
    items: [{ id: 'primary' }],
  },
});

const busySlots = res.data.calendars.primary.busy;
// busySlots is an array of { start, end } objects in ISO format
```

## Key Notes
- Use `singleEvents: true` to expand recurring events
- Use `orderBy: 'startTime'` with `singleEvents: true`
- Calendar ID `'primary'` refers to the user's primary calendar
- Dates should be in ISO 8601 format with timezone offset
- PST timezone offset is -08:00

# Gmail Send API - Node.js Skill

## Overview
Send emails using the Gmail API v1 with OAuth2 authentication.

## Setup
```bash
npm install googleapis
```

## Authentication
```javascript
const { google } = require('googleapis');

const credentials = require('./auth/gmail/credentials.json');
const tokens = require('./auth/gmail/tokens.json');

const { client_id, client_secret } = credentials.installed;
const account = tokens.accounts[tokens.defaultAccount];

const oauth2Client = new google.auth.OAuth2(client_id, client_secret);
oauth2Client.setCredentials({
  access_token: account.access_token,
  refresh_token: account.refresh_token,
});

const gmail = google.gmail({ version: 'v1', auth: oauth2Client });
```

## Sending an Email
```javascript
// Create email in RFC 2822 format
function createEmail(to, subject, body) {
  const emailLines = [
    `To: ${to}`,
    `Subject: ${subject}`,
    'Content-Type: text/plain; charset=utf-8',
    'MIME-Version: 1.0',
    '',
    body,
  ];
  const email = emailLines.join('\r\n');
  // Base64url encode the email
  const encodedEmail = Buffer.from(email)
    .toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/, '');
  return encodedEmail;
}

// Send the email
const raw = createEmail('recipient@example.com', 'Meeting Confirmation', 'Hello...');
const res = await gmail.users.messages.send({
  userId: 'me',
  requestBody: { raw },
});

console.log('Message ID:', res.data.id);
// res.data contains: { id, threadId, labelIds }
```

## Key Notes
- `userId: 'me'` refers to the authenticated user
- Email must be base64url encoded (not standard base64)
- The response `res.data.id` is the message ID to save
- Use RFC 2822 format for the raw email headers
- Content-Type should be text/plain for simple text emails

# Meeting Scheduling Logic Skill

## Overview
Logic for finding available time slots given calendar busy times and meeting constraints.

## Algorithm
1. Parse meeting request to extract: dates, time range, duration
2. Query calendar for busy times during the requested date/time range
3. Find gaps in the busy times that are >= meeting duration
4. Select the earliest available slot

## Finding Available Slots
```javascript
function findAvailableSlot(busySlots, requestedDates, startHour, endHour, durationMinutes) {
  for (const date of requestedDates) {
    // Create candidate slots in 30-minute increments
    const dayStart = new Date(date);
    dayStart.setHours(startHour, 0, 0, 0);

    const dayEnd = new Date(date);
    dayEnd.setHours(endHour, 0, 0, 0);

    for (let time = dayStart.getTime(); time + durationMinutes * 60000 <= dayEnd.getTime(); time += 30 * 60000) {
      const slotStart = new Date(time);
      const slotEnd = new Date(time + durationMinutes * 60000);

      const conflicts = busySlots.some(busy => {
        const busyStart = new Date(busy.start);
        const busyEnd = new Date(busy.end);
        return slotStart < busyEnd && slotEnd > busyStart;
      });

      if (!conflicts) {
        return { start: slotStart, end: slotEnd };
      }
    }
  }
  return null; // No available slot found
}
```

## Date/Time Formatting
```javascript
// Format: "Thursday, January 08, 2026"
function formatDate(date) {
  const days = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  const months = ['January', 'February', 'March', 'April', 'May', 'June',
                   'July', 'August', 'September', 'October', 'November', 'December'];
  const dayName = days[date.getDay()];
  const month = months[date.getMonth()];
  const dd = String(date.getDate()).padStart(2, '0');
  const yyyy = date.getFullYear();
  return `${dayName}, ${month} ${dd}, ${yyyy}`;
}

// Format: "09:00 AM - 10:30 AM"
function formatTime(date) {
  let hours = date.getHours();
  const minutes = String(date.getMinutes()).padStart(2, '0');
  const ampm = hours >= 12 ? 'PM' : 'AM';
  hours = hours % 12 || 12;
  return `${String(hours).padStart(2, '0')}:${minutes} ${ampm}`;
}

function formatTimeRange(start, end) {
  return `${formatTime(start)} - ${formatTime(end)}`;
}
```

## Key Notes
- Always iterate dates in chronological order to find earliest slot
- Check slots in 30-minute increments for granularity
- Duration can be in hours (1, 1.5) or minutes (45)
- The slot end time must not exceed the requester's available end time
- PST timezone: use explicit timezone handling

