const { google } = require('googleapis');
const fs = require('fs');

// ─── Auth Setup ───────────────────────────────────────────────
function getGmailClient() {
  const creds = JSON.parse(fs.readFileSync('/root/auth/gmail/credentials.json'));
  const tokens = JSON.parse(fs.readFileSync('/root/auth/gmail/tokens.json'));
  const { client_id, client_secret } = creds.installed;
  const account = tokens.accounts[tokens.defaultAccount];

  const oauth2 = new google.auth.OAuth2(client_id, client_secret);
  oauth2.setCredentials({
    access_token: account.access_token,
    refresh_token: account.refresh_token,
  });
  return google.gmail({ version: 'v1', auth: oauth2 });
}

function getCalendarClient() {
  const creds = JSON.parse(fs.readFileSync('/root/auth/calendar/credentials.json'));
  const tokens = JSON.parse(fs.readFileSync('/root/auth/calendar/tokens.json'));
  const { client_id, client_secret } = creds.installed;
  const account = tokens.accounts[tokens.defaultAccount];

  const oauth2 = new google.auth.OAuth2(client_id, client_secret);
  oauth2.setCredentials({
    access_token: account.access_token,
    refresh_token: account.refresh_token,
  });
  return google.calendar({ version: 'v3', auth: oauth2 });
}

// ─── Date/Time Formatting ─────────────────────────────────────
const DAY_NAMES = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const MONTH_NAMES = ['January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December'];

function formatDate(date) {
  const dayName = DAY_NAMES[date.getDay()];
  const month = MONTH_NAMES[date.getMonth()];
  const dd = String(date.getDate()).padStart(2, '0');
  const yyyy = date.getFullYear();
  return `${dayName}, ${month} ${dd}, ${yyyy}`;
}

function formatTime(date) {
  let hours = date.getHours();
  const minutes = String(date.getMinutes()).padStart(2, '0');
  const ampm = hours >= 12 ? 'PM' : 'AM';
  hours = hours % 12 || 12;
  return `${String(hours).padStart(2, '0')}:${minutes} ${ampm}`;
}

function formatTimeRange(start, end) {
  return `${formatTime(start)} - ${formatTime(end)}`;
}

// ─── Parse Meeting Requests ───────────────────────────────────
function parseMeetingRequest(emailText) {
  const result = { dates: [], startHour: 0, startMin: 0, endHour: 23, endMin: 59, durationMinutes: 60 };

  // Parse duration
  const durHourMatch = emailText.match(/(\d+(?:\.\d+)?)\s*[-\s]?\s*hour/i);
  const durMinMatch = emailText.match(/(\d+)\s*[-\s]?\s*minute/i);
  if (durHourMatch) {
    result.durationMinutes = parseFloat(durHourMatch[1]) * 60;
  } else if (durMinMatch) {
    result.durationMinutes = parseInt(durMinMatch[1]);
  }

  // Parse dates - look for "January 8th" or "January 8" patterns
  const datePatterns = emailText.matchAll(/(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+(\d{1,2})(?:st|nd|rd|th)?,?\s*(\d{4})?/gi);
  const yearMatch = emailText.match(/20\d{2}/);
  const defaultYear = yearMatch ? parseInt(yearMatch[0]) : 2026;

  const monthMap = {
    january: 0, february: 1, march: 2, april: 3, may: 4, june: 5,
    july: 6, august: 7, september: 8, october: 9, november: 10, december: 11
  };

  // Check if there's a date range pattern like "between January 8th and January 9th"
  const rangePattern = emailText.match(/between\s+(\w+)\s+(\d{1,2})(?:st|nd|rd|th)?\s+and\s+(\w+)\s+(\d{1,2})(?:st|nd|rd|th)?(?:,?\s*(\d{4}))?/i);
  const orPattern = emailText.match(/on\s+(\w+)\s+(\d{1,2})(?:st|nd|rd|th)?\s+or\s+(\d{1,2})(?:st|nd|rd|th)?(?:,?\s*(\d{4}))?/i);
  const orPattern2 = emailText.match(/on\s+(\w+)\s+(\d{1,2})(?:st|nd|rd|th)?\s+or\s+(\w+)\s+(\d{1,2})(?:st|nd|rd|th)?(?:,?\s*(\d{4}))?/i);

  if (rangePattern) {
    const month1 = monthMap[rangePattern[1].toLowerCase()];
    const day1 = parseInt(rangePattern[2]);
    const month2 = monthMap[rangePattern[3].toLowerCase()];
    const day2 = parseInt(rangePattern[4]);
    const year = rangePattern[5] ? parseInt(rangePattern[5]) : defaultYear;

    // Generate all dates in range
    const start = new Date(year, month1, day1);
    const end = new Date(year, month2, day2);
    for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
      result.dates.push(new Date(d));
    }
  } else if (orPattern2 && isNaN(parseInt(orPattern2[3]))) {
    // "on January 6th or January 7th" - two different months
    const month1 = monthMap[orPattern2[1].toLowerCase()];
    const day1 = parseInt(orPattern2[2]);
    const month2 = monthMap[orPattern2[3].toLowerCase()];
    const day2 = parseInt(orPattern2[4]);
    const year = orPattern2[5] ? parseInt(orPattern2[5]) : defaultYear;
    result.dates.push(new Date(year, month1, day1));
    result.dates.push(new Date(year, month2, day2));
  } else if (orPattern) {
    // "on January 6th or 7th" - same month
    const month = monthMap[orPattern[1].toLowerCase()];
    const day1 = parseInt(orPattern[2]);
    const day2 = parseInt(orPattern[3]);
    const year = orPattern[4] ? parseInt(orPattern[4]) : defaultYear;
    result.dates.push(new Date(year, month, day1));
    result.dates.push(new Date(year, month, day2));
  } else {
    // Single date or multiple separate dates
    for (const match of emailText.matchAll(/(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+(\d{1,2})(?:st|nd|rd|th)?(?:,?\s*(\d{4}))?/gi)) {
      const monthStr = match[0].match(/(January|February|March|April|May|June|July|August|September|October|November|December)/i)[1];
      const month = monthMap[monthStr.toLowerCase()];
      const day = parseInt(match[1]);
      const year = match[2] ? parseInt(match[2]) : defaultYear;
      result.dates.push(new Date(year, month, day));
    }
  }

  // Sort dates chronologically
  result.dates.sort((a, b) => a - b);

  // Parse time range - look for patterns like "10:00am to 2:00pm" or "9:30am and 11:30am"
  const timeRangeMatch = emailText.match(/(\d{1,2}):(\d{2})\s*(am|pm)\s*(?:to|and|-|–)\s*(\d{1,2}):(\d{2})\s*(am|pm)/i);
  const timeRangeMatch2 = emailText.match(/(\d{1,2}):(\d{2})\s*(AM|PM)\s*(?:to|and|-|–)\s*(\d{1,2}):(\d{2})\s*(AM|PM)/i);

  const tMatch = timeRangeMatch || timeRangeMatch2;
  if (tMatch) {
    let startH = parseInt(tMatch[1]);
    const startM = parseInt(tMatch[2]);
    const startAmPm = tMatch[3].toLowerCase();
    let endH = parseInt(tMatch[4]);
    const endM = parseInt(tMatch[5]);
    const endAmPm = tMatch[6].toLowerCase();

    if (startAmPm === 'pm' && startH !== 12) startH += 12;
    if (startAmPm === 'am' && startH === 12) startH = 0;
    if (endAmPm === 'pm' && endH !== 12) endH += 12;
    if (endAmPm === 'am' && endH === 12) endH = 0;

    result.startHour = startH;
    result.startMin = startM;
    result.endHour = endH;
    result.endMin = endM;
  }

  console.log('Parsed request:', {
    dates: result.dates.map(d => d.toISOString()),
    timeRange: `${result.startHour}:${String(result.startMin).padStart(2,'0')} - ${result.endHour}:${String(result.endMin).padStart(2,'0')}`,
    durationMinutes: result.durationMinutes
  });

  return result;
}

// ─── Find Available Slot ──────────────────────────────────────
function findAvailableSlot(busySlots, dates, startHour, startMin, endHour, endMin, durationMinutes) {
  for (const date of dates) {
    const dayStart = new Date(date);
    dayStart.setHours(startHour, startMin, 0, 0);

    const dayEnd = new Date(date);
    dayEnd.setHours(endHour, endMin, 0, 0);

    // Check slots in 30-minute increments
    for (let time = dayStart.getTime(); time + durationMinutes * 60000 <= dayEnd.getTime(); time += 30 * 60000) {
      const slotStart = new Date(time);
      const slotEnd = new Date(time + durationMinutes * 60000);

      const hasConflict = busySlots.some(busy => {
        const busyStart = new Date(busy.start);
        const busyEnd = new Date(busy.end);
        return slotStart < busyEnd && slotEnd > busyStart;
      });

      if (!hasConflict) {
        return { start: slotStart, end: slotEnd };
      }
    }
  }
  return null;
}

// ─── Send Email ───────────────────────────────────────────────
function createRawEmail(to, subject, body) {
  const lines = [
    `To: ${to}`,
    `Subject: ${subject}`,
    'Content-Type: text/plain; charset=utf-8',
    'MIME-Version: 1.0',
    '',
    body,
  ];
  const raw = lines.join('\r\n');
  return Buffer.from(raw).toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/, '');
}

// ─── Main ─────────────────────────────────────────────────────
async function main() {
  const gmail = getGmailClient();
  const calendar = getCalendarClient();

  const requests = JSON.parse(fs.readFileSync('/root/test_input.json', 'utf-8'));

  // Find the overall date range we need to check
  let allDates = [];
  const parsedRequests = requests.map(r => {
    const parsed = parseMeetingRequest(r.email_text);
    allDates.push(...parsed.dates);
    return { ...r, parsed };
  });

  const minDate = new Date(Math.min(...allDates.map(d => d.getTime())));
  const maxDate = new Date(Math.max(...allDates.map(d => d.getTime())));
  minDate.setHours(0, 0, 0, 0);
  maxDate.setHours(23, 59, 59, 999);

  console.log(`\nQuerying calendar from ${minDate.toISOString()} to ${maxDate.toISOString()}`);

  // Get busy times from calendar
  const calRes = await calendar.events.list({
    calendarId: 'primary',
    timeMin: minDate.toISOString(),
    timeMax: maxDate.toISOString(),
    singleEvents: true,
    orderBy: 'startTime',
  });

  const events = calRes.data.items || [];
  console.log(`\nFound ${events.length} calendar events:`);
  const busySlots = events.map(e => {
    console.log(`  ${e.summary}: ${e.start.dateTime || e.start.date} - ${e.end.dateTime || e.end.date}`);
    return {
      start: e.start.dateTime || e.start.date,
      end: e.end.dateTime || e.end.date,
    };
  });

  // Process each meeting request
  const sentResults = [];

  for (const req of parsedRequests) {
    const { parsed, from_email } = req;
    console.log(`\n--- Processing request from ${from_email} ---`);

    const slot = findAvailableSlot(
      busySlots,
      parsed.dates,
      parsed.startHour,
      parsed.startMin,
      parsed.endHour,
      parsed.endMin,
      parsed.durationMinutes
    );

    if (!slot) {
      console.log(`No available slot found for ${from_email}!`);
      continue;
    }

    const durationHours = parsed.durationMinutes / 60;
    const durationStr = durationHours % 1 === 0 ? `${durationHours}` : `${durationHours}`;

    const dateFormatted = formatDate(slot.start);
    const timeRange = formatTimeRange(slot.start, slot.end);

    const body = `Hi,

Thank you for your meeting request.

I can be available:

Date: ${dateFormatted}
Time: ${timeRange}
Duration: ${durationStr} hour(s)

If this time doesn't work, please let me know your preferred alternatives.

Best regards,
SkillsBench`;

    console.log(`\nProposed slot for ${from_email}:`);
    console.log(`  Date: ${dateFormatted}`);
    console.log(`  Time: ${timeRange}`);
    console.log(`  Duration: ${durationStr} hour(s)`);

    const raw = createRawEmail(from_email, 'Re: Meeting Request', body);
    const sendRes = await gmail.users.messages.send({
      userId: 'me',
      requestBody: { raw },
    });

    console.log(`  Sent! Message ID: ${sendRes.data.id}`);
    sentResults.push({ messageId: sendRes.data.id });
  }

  // Save results
  const output = { sent_results: sentResults };
  fs.writeFileSync('/root/results.json', JSON.stringify(output, null, 2));
  console.log('\nResults saved to /root/results.json');
  console.log(JSON.stringify(output, null, 2));
}

main().catch(err => {
  console.error('Error:', err.message);
  if (err.response) {
    console.error('Response data:', JSON.stringify(err.response.data, null, 2));
  }
  process.exit(1);
});

