# The refresh token generates cloud-platform scoped tokens.
# Google Calendar API explicitly requires calendar scopes and doesn't accept cloud-platform.
# However, maybe if we use the Calendar API REST endpoint via the correct project with 
# the Calendar API enabled, it might work differently.
# 
# Actually, wait - let me reread the scope claim. The Google Calendar API documentation says:
# "Note: The https://www.googleapis.com/auth/cloud-platform scope provides no access to 
#  the Google Calendar API. You must use calendar-specific scopes."
# 
# So we genuinely can't use the refresh token for calendar access.
# BUT - the gmail tokens might work differently. Let me first check if gmail works.

node -e "
const { google } = require('googleapis');
const fs = require('fs');

async function test() {
  const creds = JSON.parse(fs.readFileSync('/root/auth/gmail/credentials.json'));
  const tokens = JSON.parse(fs.readFileSync('/root/auth/gmail/tokens.json'));
  const { client_id, client_secret } = creds.installed;
  const account = tokens.accounts[tokens.defaultAccount];

  const oauth2 = new google.auth.OAuth2(client_id, client_secret);
  oauth2.setCredentials({ refresh_token: account.refresh_token });

  const gmail = google.gmail({ version: 'v1', auth: oauth2 });

  // Check if gmail works
  const profile = await gmail.users.getProfile({ userId: 'me' });
  console.log('Gmail profile:', JSON.stringify(profile.data));
}
test().catch(e => console.error('Gmail error:', e.message));
" 2>&1

