# The Admin SDK token management needs specific admin scopes.
# cloud-platform scope only gives access to some Admin endpoints (like users.list).
#
# Let me step way back and think about what's really going on here.
# 
# The task says to check /root/auth/gmail/ and /root/auth/calendar/ for authentication.
# These files have:
# - credentials.json (client_id, client_secret for gcloud CLI)
# - tokens.json (refresh_token + access_token)
#
# The access_tokens in tokens.json were valid but are now expired.
# The refresh_token can only get cloud-platform scoped tokens.
#
# BUT: the Node.js googleapis library, when it gets a 401, automatically tries 
# to refresh the token. If I set the access_token to the one from tokens.json 
# AND set forceRefreshOnFailure to false, maybe it will try the original token first.
#
# Wait, the original tokens are expired (401 error). That's the problem.
#
# Let me look at this from the Node.js side more carefully.
# Maybe the Node.js library handles the token files differently.

# Actually, let me try another completely different approach.
# The googleapis Node.js library supports reading credentials from a file format
# where the access_token is embedded. Let me try setting the token explicitly
# AND preventing auto-refresh.

node -e "
const { google } = require('googleapis');
const fs = require('fs');

async function test() {
  const creds = JSON.parse(fs.readFileSync('/root/auth/gmail/credentials.json'));
  const tokens = JSON.parse(fs.readFileSync('/root/auth/gmail/tokens.json'));
  const { client_id, client_secret } = creds.installed;
  const account = tokens.accounts[tokens.defaultAccount];

  const oauth2 = new google.auth.OAuth2(client_id, client_secret);

  // Set credentials with the stored access_token and a very far future expiry
  oauth2.setCredentials({
    access_token: account.access_token,
    refresh_token: account.refresh_token,
    expiry_date: account.expiry_date,
    token_type: 'Bearer',
    scope: account.scope,
  });

  // Check if the token is valid by seeing if getAccessToken returns the stored one
  try {
    const { token } = await oauth2.getAccessToken();
    console.log('Token (first 30):', token.substring(0, 30));
    console.log('Is original:', token === account.access_token);
  } catch(e) {
    console.log('getAccessToken error:', e.message);
  }

  // Try to use the Gmail API
  const gmail = google.gmail({ version: 'v1', auth: oauth2 });
  try {
    const profile = await gmail.users.getProfile({ userId: 'me' });
    console.log('Profile:', JSON.stringify(profile.data));
  } catch(e) {
    console.log('Gmail error:', e.message.substring(0, 200));
  }
}
test();
" 2>&1

export CLOUDSDK_CONFIG=/tmp/gcloud_config
SA_TOKEN=$(gcloud auth print-access-token 2>/dev/null)
echo "Token length: ${#SA_TOKEN}"
echo "Token prefix: ${SA_TOKEN:0:30}"

# Test this token with calendar
node -e "
async function test() {
  const token = '$SA_TOKEN';

  // Try Calendar API
  const calUrl = 'https://www.googleapis.com/calendar/v3/calendars/primary/events?timeMin=2026-01-06T00:00:00Z&timeMax=2026-01-10T00:00:00Z&singleEvents=true&orderBy=startTime';
  const calRes = await fetch(calUrl, { headers: { 'Authorization': 'Bearer ' + token } });
  const calData = await calRes.json();

  if (calData.error) {
    console.log('Calendar error:', JSON.stringify(calData.error, null, 2).substring(0, 200));
  } else {
    console.log('Calendar events:', calData.items?.length || 0);
  }

  // Try Gmail API
  const gmailUrl = 'https://gmail.googleapis.com/gmail/v1/users/me/profile';
  const gmailRes = await fetch(gmailUrl, { headers: { 'Authorization': 'Bearer ' + token } });
  const gmailData = await gmailRes.json();

  if (gmailData.error) {
    console.log('Gmail error:', JSON.stringify(gmailData.error, null, 2).substring(0, 200));
  } else {
    console.log('Gmail profile:', JSON.stringify(gmailData));
  }
}
test();
" 2>&1

